package main
import("encoding/hex";"testing")
func TestLTECellMeasurement(t *testing.T){v,_:=hex.DecodeString("0064f00011352baa5d031405d1000000000005d10038ff27fcbffd0000ce0066ff26fc23fd0000050163ff1dfc23fd0000800170ff2bfc23fd0000cf0040ff00fc23fd0000");cells,pci,ch,id,e:=parseLTECells(map[byte][]byte{0x13:v});if e!=nil||len(cells)!=5||pci!=209||ch!=1300||id!=56470059||!cells[0].Serving||cells[0].RSRP!=-98.5{t.Fatalf("%+v %d %d %d %v",cells,pci,ch,id,e)};_,_,_,_,e=parseLTECells(map[byte][]byte{0x13:v[:len(v)-1]});if e==nil{t.Fatal("accepted truncated measurement")}}
func TestLTELockKnownVersusMissing(t *testing.T){if parseLTELock(map[byte][]byte{}).Known{t.Fatal("ack-only treated as unlocked")};s:=parseLTELock(map[byte][]byte{0x10:{0}});if !s.Known||len(s.Cells)!=0{t.Fatal(s)}}
func TestLTELockEncoding(t *testing.T){b,e:=lteLockPayload(209,1300,false);if e!=nil||hex.EncodeToString(b)!="01070001d1001405000010010001"{t.Fatalf("%x %v",b,e)};if _,e=lteLockPayload(504,1300,false);e==nil{t.Fatal("PCI out of range")};b,e=lteLockPayload(0,0,true);if e!=nil||hex.EncodeToString(b)!="0101000010010001"{t.Fatal("bad unlock")}}
func TestQMIResponseValidation(t *testing.T){b,_:=hex.DecodeString("020100d7000b000204000000000010010000");m,e:=parseQMIFrame(b,0xd7);if e!=nil||!parseLTELock(m).Known{t.Fatal(e)};b[5]++;if _,e=parseQMIFrame(b,0xd7);e==nil{t.Fatal("accepted wrong frame length")}}
